'use client';

import * as React from 'react';
import { Button as BaseButton } from '@base-ui/react/button';
import './button.css';

/**
 * Which cap the button wears. `standard` is soft-touch in the colorway,
 * `primary` is the dark cap, and `destructive` is the one red cap. Use at
 * most one primary or destructive cap per group.
 */
export type ButtonCap = 'standard' | 'primary' | 'destructive';

export interface ButtonProps extends BaseButton.Props {
  cap?: ButtonCap;
  /** default: 32 tall. compact: 28, 12 pt, raise-sm (the medium's pills: "seed a sample day", "lenses ⌘K"). */
  size?: 'default' | 'compact';
}

/**
 * A press-in pill button (KAMUI-15). While held it sinks 1px and its shadow
 * collapses into a well; on release it springs back. MetalUI icons inside it
 * play their hover pose and press one-shot from the whole button.
 */
export const Button = React.forwardRef<HTMLElement, ButtonProps>(function Button(
  { cap = 'standard', size = 'default', className, ...props },
  ref,
) {
  return (
    <BaseButton
      ref={ref}
      data-cap={cap}
      data-size={size}
      className={(state) => {
        const extra = typeof className === 'function' ? className(state) : className;
        return extra ? `mu-button mu-icon-trigger ${extra}` : 'mu-button mu-icon-trigger';
      }}
      {...props}
    />
  );
});

@import "../tokens.css";

/* Button (the object sheet's .btn; compact is the reference design's .pill). Its look is the button recipe
   (--mu-r-button-*); --mu-button-h and --mu-button-px override one instance (the docs dials). */
.mu-button {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--mu-r-button-self-gap);
  height: var(--mu-button-h, var(--mu-r-button-self-height));
  margin: var(--mu-zero);
  padding: var(--mu-zero) var(--mu-button-px, var(--mu-r-button-self-pad));
  border: 0;
  border-radius: var(--mu-radius-pill);
  font: var(--mu-type-ui);
  letter-spacing: var(--mu-type-ui-tracking);
  white-space: nowrap;
  color: var(--mu-ink);
  background: var(--mu-r-button-self-background);
  box-shadow: var(--mu-r-button-self-shadow);
  cursor: pointer;
  user-select: none;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  transition:
    transform var(--mu-spring-release-d) var(--mu-spring-release),
    box-shadow var(--mu-r-button-self-fade),
    background var(--mu-r-button-self-fade),
    color var(--mu-r-button-self-fade);
}
.mu-button > svg { width: var(--mu-r-button-self-glyph); height: var(--mu-r-button-self-glyph); flex: none; }

.mu-button:active:not([data-disabled]) {
  transform: translateY(var(--mu-r-button-self-travel));
  /* Down in 50 ms, linear; back on release. */
  transition-duration: var(--mu-r-button-self-press);
  transition-timing-function: linear;
  background: var(--mu-r-button-self-pressed-background);
  box-shadow: var(--mu-r-button-self-pressed-shadow);
}

.mu-button[data-cap="primary"] {
  color: var(--mu-primary-ink);
  background: var(--mu-primary-bg);
  box-shadow: var(--mu-primary-sh);
}
.mu-button[data-cap="primary"]:active:not([data-disabled]) {
  background: var(--mu-primary-pressed-bg);
  box-shadow: var(--mu-primary-pressed-sh);
}

.mu-button[data-cap="destructive"] {
  color: var(--mu-destructive-ink);
  background: var(--mu-destructive-bg);
  box-shadow: var(--mu-destructive-sh);
}
.mu-button[data-cap="destructive"]:active:not([data-disabled]) {
  background: var(--mu-destructive-pressed-bg);
  box-shadow: var(--mu-destructive-pressed-sh);
}

.mu-button:focus-visible {
  outline: var(--mu-r-button-self-focus-width) solid var(--mu-focus);
  outline-offset: var(--mu-r-button-self-focus-offset);
}

.mu-button[data-disabled] {
  opacity: var(--mu-r-button-self-disabled);
  cursor: default;
}

/* Compact: the canvas pill (the reference design's .pill): 26 tall, raised, ink2 until hover, pressed into a shallow well. */
.mu-button[data-size="compact"] {
  gap: var(--mu-r-button-compact-gap);
  height: var(--mu-button-h, var(--mu-r-button-compact-height));
  padding: var(--mu-zero) var(--mu-button-px, var(--mu-r-button-compact-pad));
  font: var(--mu-r-button-compact-font);
  letter-spacing: var(--mu-r-button-compact-tracking);
  color: var(--mu-ink2);
  background: var(--mu-r-button-compact-background);
  box-shadow: var(--mu-r-button-compact-shadow);
  transition: transform var(--mu-r-button-compact-move), box-shadow var(--mu-r-button-compact-move);
}
.mu-button[data-size="compact"]:hover { color: var(--mu-ink); }
.mu-button[data-size="compact"]:active:not([data-disabled]) { background: var(--mu-r-button-compact-background); box-shadow: var(--mu-r-button-compact-pressed-shadow); }
.mu-button[data-size="compact"] > svg { width: var(--mu-r-button-compact-glyph); height: var(--mu-r-button-compact-glyph); }
